#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>

#define MAX_MSG_SIZE 4096
#define MAX_PAYLOAD_SIZE 2048
#define HMAC_KEY_SIZE 32
#define HEADER_SIZE 12
#define MAX_CHUNKS 64

/* HMAC secret is loaded at runtime from a secure source rather than being
 * hard-coded in the binary (CWE-798). */
static unsigned char HMAC_SECRET[HMAC_KEY_SIZE];

/* Load the HMAC key from an environment variable pointing to a key file.
 * Returns 0 on success, -1 on failure. */
static int load_hmac_secret(void) {
    const char *key_path = getenv("HMAC_KEY_FILE");
    if (key_path == NULL) {
        fprintf(stderr, "HMAC_KEY_FILE environment variable not set\n");
        return -1;
    }

    FILE *f = fopen(key_path, "rb");
    if (f == NULL) {
        perror("fopen key file");
        return -1;
    }

    size_t read_len = fread(HMAC_SECRET, 1, HMAC_KEY_SIZE, f);
    fclose(f);

    if (read_len != HMAC_KEY_SIZE) {
        fprintf(stderr, "Key file must contain exactly %d bytes\n", HMAC_KEY_SIZE);
        /* Wipe any partial key material */
        memset(HMAC_SECRET, 0, HMAC_KEY_SIZE);
        return -1;
    }

    return 0;
}

typedef struct {
    uint16_t msg_type;
    uint16_t chunk_count;
    uint32_t total_length;
    uint32_t session_id;
} __attribute__((packed)) msg_header_t;

typedef struct {
    uint16_t chunk_id;
    uint16_t chunk_length;
    uint32_t data_offset;
} __attribute__((packed)) chunk_descriptor_t;

typedef struct {
    char buffer[MAX_PAYLOAD_SIZE];
    size_t used;
} payload_buffer_t;

/* Verify HMAC-SHA256 of the message */
static int verify_message_hmac(const unsigned char *data, size_t data_len,
                               const unsigned char *received_hmac) {
    unsigned char computed[SHA256_DIGEST_LENGTH];
    unsigned int computed_len = 0;

    HMAC(EVP_sha256(), HMAC_SECRET, HMAC_KEY_SIZE,
         data, data_len, computed, &computed_len);

    /* Constant-time comparison to prevent timing attacks */
    int result = 0;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        result |= computed[i] ^ received_hmac[i];
    }
    return result == 0;
}

/* Validate chunk descriptor bounds */
static int validate_chunk_bounds(const chunk_descriptor_t *chunk,
                                  size_t payload_capacity) {
    /* Ensure chunk_length is reasonable */
    if (chunk->chunk_length > MAX_PAYLOAD_SIZE) {
        return 0;
    }

    /* Ensure data_offset is within capacity */
    if (chunk->data_offset >= payload_capacity) {
        return 0;
    }

    /* Check that data_offset + chunk_length doesn't exceed capacity */
    size_t remaining = payload_capacity - chunk->data_offset;
    if (chunk->chunk_length > remaining) {
        return 0;
    }

    return 1;
}

/* Copy chunk data into the payload buffer with bounds checking */
static int copy_chunk_to_buffer(payload_buffer_t *payload,
                                 const chunk_descriptor_t *chunk,
                                 const unsigned char *src_data,
                                 size_t src_available) {
    /* Validate source has enough data */
    if (chunk->chunk_length > src_available) {
        return -1;
    }

    /* Calculate destination position using the offset */
    size_t dest_pos = payload->used + chunk->data_offset;

    /* Bounds check: ensure we don't write past buffer end */
    if (dest_pos > MAX_PAYLOAD_SIZE) {
        return -1;
    }
    if (chunk->chunk_length > MAX_PAYLOAD_SIZE - dest_pos) {
        return -1;
    }

    memcpy(payload->buffer + dest_pos, src_data, chunk->chunk_length);

    /* Update used tracker */
    size_t new_end = dest_pos + chunk->chunk_length;
    if (new_end > payload->used) {
        payload->used = new_end;
    }

    return 0;
}

/* Process a reassembly message containing multiple chunks */
static int process_reassembly_message(const unsigned char *msg, size_t msg_len) {
    /* Minimum: header + HMAC */
    if (msg_len < HEADER_SIZE + SHA256_DIGEST_LENGTH) {
        fprintf(stderr, "Message too short\n");
        return -1;
    }

    /* HMAC is at the end of the message */
    size_t data_len = msg_len - SHA256_DIGEST_LENGTH;
    const unsigned char *hmac_ptr = msg + data_len;

    /* Verify integrity first */
    if (!verify_message_hmac(msg, data_len, hmac_ptr)) {
        fprintf(stderr, "HMAC verification failed\n");
        return -1;
    }

    /* Parse header */
    const msg_header_t *header = (const msg_header_t *)msg;
    uint16_t chunk_count = ntohs(header->chunk_count);
    uint32_t total_length = ntohl(header->total_length);

    /* Validate chunk count */
    if (chunk_count == 0 || chunk_count > MAX_CHUNKS) {
        fprintf(stderr, "Invalid chunk count: %u\n", chunk_count);
        return -1;
    }

    /* Validate total_length against payload capacity */
    if (total_length > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Total length exceeds maximum: %u\n", total_length);
        return -1;
    }

    /* Calculate expected minimum message size */
    size_t descriptors_size = (size_t)chunk_count * sizeof(chunk_descriptor_t);
    size_t min_msg_size = HEADER_SIZE + descriptors_size + SHA256_DIGEST_LENGTH;
    if (msg_len < min_msg_size) {
        fprintf(stderr, "Message too short for descriptors\n");
        return -1;
    }

    /* Parse chunk descriptors */
    const chunk_descriptor_t *descriptors = 
        (const chunk_descriptor_t *)(msg + HEADER_SIZE);

    /* Data starts after all descriptors */
    const unsigned char *chunk_data_start = msg + HEADER_SIZE + descriptors_size;
    size_t chunk_data_available = data_len - HEADER_SIZE - descriptors_size;

    /* Initialize payload buffer */
    payload_buffer_t payload;
    memset(&payload, 0, sizeof(payload));

    /* Process each chunk */
    size_t data_cursor = 0;
    for (uint16_t i = 0; i < chunk_count; i++) {
        chunk_descriptor_t chunk;
        chunk.chunk_id = ntohs(descriptors[i].chunk_id);
        chunk.chunk_length = ntohs(descriptors[i].chunk_length);
        chunk.data_offset = ntohl(descriptors[i].data_offset);

        /* Validate this chunk's bounds against total buffer capacity */
        size_t capacity_remaining = MAX_PAYLOAD_SIZE - payload.used;
        if (!validate_chunk_bounds(&chunk, capacity_remaining)) {
            fprintf(stderr, "Chunk %u failed bounds validation\n", i);
            return -1;
        }

        /* Ensure we have enough source data */
        if (data_cursor + chunk.chunk_length > chunk_data_available) {
            fprintf(stderr, "Insufficient source data for chunk %u\n", i);
            return -1;
        }

        /* Copy chunk data to reassembly buffer */
        if (copy_chunk_to_buffer(&payload, &chunk,
                                  chunk_data_start + data_cursor,
                                  chunk_data_available - data_cursor) != 0) {
            fprintf(stderr, "Failed to copy chunk %u\n", i);
            return -1;
        }

        data_cursor += chunk.chunk_length;
    }

    printf("Successfully reassembled %zu bytes from %u chunks\n",
           payload.used, chunk_count);
    return 0;
}

int main(int argc, char *argv[]) {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    unsigned char recv_buf[MAX_MSG_SIZE];

    /* Load the HMAC secret from a secure external source before serving. */
    if (load_hmac_secret() != 0) {
        fprintf(stderr, "Failed to load HMAC secret; aborting\n");
        return 1;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");
    server_addr.sin_port = htons(9999);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(sockfd);
        return 1;
    }

    printf("Chunk reassembly server listening on 127.0.0.1:9999\n");

    while (1) {
        ssize_t recv_len = recvfrom(sockfd, recv_buf, MAX_MSG_SIZE, 0,
                                     (struct sockaddr *)&client_addr, &client_len);
        if (recv_len < 0) {
            perror("recvfrom");
            continue;
        }

        process_reassembly_message(recv_buf, (size_t)recv_len);
    }

    close(sockfd);
    return 0;
}
